from pathlib import Path
from typing import Final

import pytest

NOTES_DIR: Final = Path("notes")


def read_note(name: str) -> str:
    """Return the text of file `name` inside the directory NOTES_DIR.

    NOTES_DIR is resolved against the current working directory. Only regular
    files that resolve to a location inside NOTES_DIR are read. A missing,
    unreadable, or out-of-bounds name (absolute paths, `..` traversal, symlinks
    that escape the directory) yields an empty string.
    """
    try:
        root = NOTES_DIR.resolve()
        target = (root / name).resolve()
        if not target.is_relative_to(root):
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError):
        return ""


@pytest.fixture
def workdir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    notes.mkdir()
    (notes / "a.txt").write_text("hello", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("top secret", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_existing_note(workdir: Path) -> None:
    assert read_note("a.txt") == "hello"


def test_missing_note_is_empty(workdir: Path) -> None:
    assert read_note("nope.txt") == ""


def test_empty_name_is_empty(workdir: Path) -> None:
    assert read_note("") == ""


def test_directory_name_is_empty(workdir: Path) -> None:
    (workdir / "notes" / "sub").mkdir()
    assert read_note("sub") == ""


def test_parent_traversal_is_blocked(workdir: Path) -> None:
    assert read_note("../secret.txt") == ""


def test_nested_traversal_is_blocked(workdir: Path) -> None:
    assert read_note("sub/../../secret.txt") == ""


def test_absolute_path_outside_is_blocked(workdir: Path) -> None:
    assert read_note(str(workdir / "secret.txt")) == ""


def test_symlink_escaping_notes_is_blocked(workdir: Path) -> None:
    (workdir / "notes" / "link.txt").symlink_to(workdir / "secret.txt")
    assert read_note("link.txt") == ""


def test_symlink_inside_notes_is_followed(workdir: Path) -> None:
    (workdir / "notes" / "alias.txt").symlink_to(workdir / "notes" / "a.txt")
    assert read_note("alias.txt") == "hello"
